pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var client: std.http.Client = .{ .allocator = allocator };
    defer client.deinit();

    const payload =
        \\{"model":"accounts/fireworks/models/glm-5p1","max_tokens":16384,"top_p":1,"top_k":40,"presence_penalty":0,"frequency_penalty":0,"temperature":0,"messages":[{"role":"user","content":"Hello, how are you?"}],"echo":false}
    ;

    var body = std.ArrayList(u8).init(allocator);
    defer body.deinit();

    const result = try client.fetch(.{
        .location = .{ .url = "" },
        .method = .POST,
        .headers = .{
            .content_type = .{ .override = "application/json" },
            .authorization = .{ .override = "Bearer <API_KEY>" },
        },
        .extra_headers = &[_]std.http.Header{
            .{ .name = "Accept", .value = "application/json" },
        },
        .payload = payload,
        .response_storage = .{ .dynamic = &body },
    });

    _ = result;

    std.debug.print("{s}\n", .{body.items});
}



