const std = @import("std");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const url = "";

    const payload =
        \\{
        \\  "model": "accounts/fireworks/models/glm-5p1",
        \\  "max_tokens": 16384,
        \\  "top_p": 1,
        \\  "top_k": 40,
        \\  "presence_penalty": 0,
        \\  "frequency_penalty": 0,
        \\  "temperature": 0,
        \\  "messages": [
        \\    {
        \\      "role": "user",
        \\      "content": "Hello, how are you?"
        \\    }
        \\  ],
        \\  "echo": false
        \\}
    ;

    var uri = try std.Uri.parse(url);

    var http_client = std.http.Client{ .allocator = allocator };
    defer http_client.deinit();

    const headers_buf = try allocator.alloc(u8, 1024 * 16);
    defer allocator.free(headers_buf);

    var req = try http_client.open(.POST, uri, .{
        .server_header_buffer = headers_buf,
        .extra_headers = &[_]std.http.Header{
            .{ .name = "Accept", .value = "application/json" },
            .{ .name = "Content-Type", .value = "application/json" },
            .{ .name = "Authorization", .value = "Bearer <API_KEY>" },
        },
    });
    defer req.deinit();

    req.transfer_encoding = .{ .content_length = payload.len };

    try req.send();
    try req.writeAll(payload);
    try req.finish();
    try req.wait();

    const response_body = try req.reader().readAllAlloc(allocator, 1024 * 1024 * 10);
    defer allocator.free(response_body);

    const stdout = std.io.getStdOut().writer();
    try stdout.print("{s}\n", .{response_body});
}


